namespace sv_ebb8e4f8817b45c9a232a09e9741e7dd.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// Each user/circuit gets its own instance via DI scoping.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Mode or AccentColor changes.
    /// Subscribers call StateHasChanged to re-render.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@implements IDisposable
@inject Services.ThemeService Theme

<CascadingValue Value="Theme" IsFixed="false">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    protected override void OnInitialized()
    {
        Theme.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= OnThemeChanged;
    }
}

@implements IDisposable
@inject Services.ThemeService Theme

<span class="theme-indicator" style="color: @Theme.AccentColor;" title="Current theme">
    @Icon @Theme.Mode
</span>

@code {
    private string Icon => Theme.Mode switch
    {
        Services.ThemeMode.Dark => "🌙",
        Services.ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        Theme.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        Theme.OnChange -= OnThemeChanged;
    }
}

@page "/settings"

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <button class="btn @(Theme.Mode == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => Theme.Mode = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-2 mb-3">
        <input type="color" value="@Theme.AccentColor"
               @onchange="e => Theme.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
        <span style="color: @Theme.AccentColor;">@Theme.AccentColor</span>
    </div>

    <p class="text-muted mb-0">
        Changes apply instantly to all components, including the header indicator.
    </p>
</div>

@code {
    [CascadingParameter]
    private Services.ThemeService Theme { get; set; } = default!;
}

