@page "/settings"

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <button class="btn @(Theme.Mode == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => Theme.Mode = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-2 mb-3">
        <input type="color" value="@Theme.AccentColor"
               @onchange="e => Theme.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
        <span style="color: @Theme.AccentColor;">@Theme.AccentColor</span>
    </div>

    <p class="text-muted mb-0">
        Changes apply instantly to all components, including the header indicator.
    </p>
</div>

@code {
    [CascadingParameter]
    private Services.ThemeService Theme { get; set; } = default!;
}

